 cons=["No one can predict when seasons will change", "Bear markets can last longer than expected", "Recoveries can take years", "Emotions can still run high"],
 watch=["Never invest money you need soon in stocks.", "Avoid borrowing to invest, especially in a bull market.", "Do not sell in a panic during a bear market.", "Be skeptical of anyone who claims to know when the market will turn."],
