 verse=["To every thing there is a season, and a time to every purpose under the heaven.", "Ecclesiastes 3:1"],
 check=["Write your one-page storm plan", "Check that near-term money is out of stocks", "Unfollow one fear-driven financial news source", "Decide how often you will check your investments"],
