  dict(q="A decline of 10% to 20% is usually called:", o=["A correction", "A bull market", "A recession"], a=0, why="Corrections are common."),
  dict(q="In a bear market, a wise response is to:", o=["Sell everything in a panic", "Keep investing if you can and avoid panic selling", "Borrow to buy more"], a=1, why="Lower prices mean more shares for your regular amount."),
  dict(q="Historically, U.S. bear markets have tended to be:", o=["Shorter than bull markets", "Permanent", "Longer than every bull market"], a=0, why="But recoveries can still take years."),
  dict(q="Joseph's example teaches us to:", o=["Prepare in plenty for times of famine", "Spend in plenty", "Fear every season"], a=0, why="Genesis 41 shows wise preparation."),
