  dict(q="The balance sheet shows:", o=["Assets, liabilities, and equity", "Only revenue", "Stock prices"], a=0, why="It shows what is owned and owed."),
  dict(q="Assets equal:", o=["Liabilities plus equity", "Revenue minus costs", "Cash only"], a=0, why="The balance sheet always balances."),
  dict(q="The cash flow statement shows:", o=["Where cash came from and went", "Only profit", "Share price"], a=0, why="Cash is not the same as profit."),
  dict(q="Free cash flow equals:", o=["Cash from operations minus capital expenditures", "Revenue", "Net income plus debt"], a=0, why="It shows cash available to use."),
  dict(q="Net income is:", o=["The bottom line, profit after all expenses", "Total sales", "Cash on hand"], a=0, why="It is at the bottom of the income statement."),
  dict(q="Rising profits with falling operating cash flow is:", o=["A reason to investigate", "Always good", "Impossible"], a=0, why="Paper profits may not be real cash."),
  dict(q="When reading statements, compare:", o=["Several years", "One quarter only", "Nothing"], a=0, why="Trends reveal the story."),
  dict(q="Shareholders' equity is:", o=["Assets minus liabilities", "Total debt", "Revenue"], a=0, why="It is what belongs to owners."),
